CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY, email VARCHAR(320) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, name VARCHAR(120) NOT NULL, role VARCHAR(20) NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS meals (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, image_url TEXT, image_hash VARCHAR(64) NOT NULL, detected_foods_json JSONB NOT NULL, nutrition_data_json JSONB NOT NULL, health_score INTEGER NOT NULL, grade VARCHAR(1) NOT NULL, recommendations_json JSONB NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE INDEX IF NOT EXISTS idx_meals_user_created ON meals(user_id, created_at DESC);
CREATE TABLE IF NOT EXISTS meal_foods (id UUID PRIMARY KEY, meal_id UUID NOT NULL REFERENCES meals(id) ON DELETE CASCADE, food_name VARCHAR(200) NOT NULL, confidence REAL NOT NULL, calories_per_100g REAL, position INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS nutrition_data (id UUID PRIMARY KEY, food_name VARCHAR(200) NOT NULL UNIQUE, calories_per_100g REAL NOT NULL DEFAULT 0, proteins REAL NOT NULL DEFAULT 0, carbs REAL NOT NULL DEFAULT 0, fats REAL NOT NULL DEFAULT 0, fiber REAL NOT NULL DEFAULT 0, sodium REAL NOT NULL DEFAULT 0, sugar_total REAL NOT NULL DEFAULT 0);
